from fractions import Fraction

def get_neighbors(r):
    neighbors = set()
    # r + r' = 0 => r' = -r
    r1 = -r
    if r1 != r:
        neighbors.add(r1)
    # r + r' = 1 => r' = 1-r
    r2 = 1 - r
    if r2 != r:
        neighbors.add(r2)
    # rr' = 1 => r' = 1/r
    if r != 0:
        r3 = 1 / r
        if r3 != r:
            neighbors.add(r3)
    return neighbors

def get_orbit(start_r):
    orbit = {start_r}
    queue = [start_r]
    while queue:
        curr = queue.pop(0)
        for neighbor in get_neighbors(curr):
            if neighbor not in orbit:
                orbit.add(neighbor)
                queue.append(neighbor)
    return orbit

def get_distance(start_r, target_r):
    if start_r == target_r:
        return 0
    queue = [(start_r, 0)]
    visited = {start_r}
    while queue:
        curr, dist = queue.pop(0)
        for neighbor in get_neighbors(curr):
            if neighbor == target_r:
                return dist + 1
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, dist + 1))
    return None

