def get_matrix(m):
    # m is a tuple of (a, b, c, d) representing [[a, b], [c, d]]
    return np.array(m)

def normalize(m):
    # Normalize the matrix to have first non-zero entry as 1
    # However, in PGL_2, we can also divide by -1
    if m[0, 0] == 0 and m[0, 1] == 0:
        if m[1, 0] == -1:
            return -m
    elif m[0, 0] == -1:
        return -m
    return m

def get_group(generators):
    group = set()
    # Each element is a tuple of (a, b, c, d)
    initial = tuple(map(tuple, generators))
    # Actually, let's just use a set of tuples
    group = set()
    for g in generators:
        group.add(tuple(map(tuple, g)))

    queue = list(group)
    while queue:
        curr = queue.pop(0)
        curr_mat = np.array(curr)
        for gen in generators:
            gen_mat = np.array(gen)
            res = np.dot(curr_mat, gen_mat)
            # Normalize
            if res[0, 0] == -1 or (res[0, 0] == 0 and res[0, 1] == -1) or (res[0, 0] == 0 and res[0, 1] == 0 and res[1, 0] == -1):
                res = -res
            res_tuple = tuple(map(tuple, res))
            if res_tuple not in group:
                group.add(res_tuple)
                queue.append(res_tuple)
    return group

